-- P13-02 (2026-11-25) — the validation rules of the pedagogical referential
-- (section 2, rule V10; section 3, Skills Passport), GENERATED by a script:
--   - a module QCM is a bank; a session draws 5 questions, choices shuffled;
--     a new session prefers questions not seen in the last one;
--   - a "critique" question must be answered right, whatever the average;
--   - one row per module: its exercise and corrected answer
--     (graded on its five-step grid), mission, proof, level;
--   - the Skills Passport: per person and module, exercise, mission and the
--     weighted score 0.50 × QCM + 0.30 × exercise + 0.20 × mission.

ALTER TABLE `quizzes` ADD COLUMN `drawCount` INTEGER NULL;
ALTER TABLE `quizzes` ADD CONSTRAINT `chk_quiz_draw_count` CHECK (`drawCount` IS NULL OR `drawCount` >= 1);
ALTER TABLE `quiz_questions` ADD COLUMN `critical` BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE `quiz_attempts` ADD COLUMN `choiceOrder` JSON NULL;
ALTER TABLE `quiz_attempts` ADD COLUMN `criticalErrors` INTEGER NULL;

CREATE TABLE `fin_academy_modules` (
    `id` VARCHAR(191) NOT NULL,
    `formationId` VARCHAR(191) NOT NULL,
    `courseId` VARCHAR(191) NOT NULL,
    `quizId` VARCHAR(191) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `title` VARCHAR(190) NOT NULL,
    `level` VARCHAR(20) NOT NULL DEFAULT '',
    `exercise` TEXT NOT NULL,
    `correction` TEXT NOT NULL,
    `mission` TEXT NOT NULL,
    `challenge` TEXT NOT NULL,
    `tool` VARCHAR(120) NOT NULL DEFAULT '',
    `proof` TEXT NOT NULL,
    `evidenceType` VARCHAR(12) NOT NULL,
    `regulatory` BOOLEAN NOT NULL DEFAULT false,
    `contentVersion` VARCHAR(20) NOT NULL,

    UNIQUE INDEX `fin_academy_modules_courseId_key`(`courseId`),
    UNIQUE INDEX `fin_academy_modules_quizId_key`(`quizId`),
    INDEX `fin_academy_modules_formationId_idx`(`formationId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `fin_academy_modules` ADD CONSTRAINT `chk_academy_module_evidence` CHECK (`evidenceType` IN ('budget', 'simulation', 'checklist', 'tableau', 'document', 'cas'));
ALTER TABLE `fin_academy_modules` ADD CONSTRAINT `fin_academy_modules_formationId_fkey` FOREIGN KEY (`formationId`) REFERENCES `formations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_academy_modules` ADD CONSTRAINT `fin_academy_modules_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_academy_modules` ADD CONSTRAINT `fin_academy_modules_quizId_fkey` FOREIGN KEY (`quizId`) REFERENCES `quizzes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE `fin_skill_records` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `moduleId` VARCHAR(191) NOT NULL,
    `exerciseAnswer` TEXT NOT NULL,
    `exerciseSteps` JSON NULL,
    `exerciseScore` INTEGER NULL,
    `missionStatus` VARCHAR(10) NOT NULL DEFAULT 'todo',
    `evidenceRef` VARCHAR(300) NOT NULL DEFAULT '',
    `qcmScore` INTEGER NULL,
    `criticalErrors` INTEGER NOT NULL DEFAULT 0,
    `masteryScore` INTEGER NULL,
    `validatedAt` DATETIME(3) NULL,
    `refreshDue` DATETIME(3) NULL,
    `contentVersion` VARCHAR(20) NOT NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    UNIQUE INDEX `fin_skill_records_userId_moduleId_key`(`userId`, `moduleId`),
    INDEX `fin_skill_records_moduleId_idx`(`moduleId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `fin_skill_records` ADD CONSTRAINT `chk_skill_record_values` CHECK (`missionStatus` IN ('todo', 'done') AND (`exerciseScore` IS NULL OR `exerciseScore` BETWEEN 0 AND 100) AND (`qcmScore` IS NULL OR `qcmScore` BETWEEN 0 AND 100) AND (`masteryScore` IS NULL OR `masteryScore` BETWEEN 0 AND 100) AND `criticalErrors` >= 0);
ALTER TABLE `fin_skill_records` ADD CONSTRAINT `fin_skill_records_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `fin_skill_records` ADD CONSTRAINT `fin_skill_records_moduleId_fkey` FOREIGN KEY (`moduleId`) REFERENCES `fin_academy_modules`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

