INSERT IGNORE INTO `fin_academy_modules` (`id`, `formationId`, `courseId`, `quizId`, `code`, `title`, `level`, `exercise`, `correction`, `mission`, `challenge`, `tool`, `proof`, `evidenceType`, `regulatory`, `contentVersion`) VALUES ('71959418-f8f1-5df8-ace8-380324f90e07', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', '561ce612-cb22-5990-ab7a-0129df51b407', '4b0390a2-a317-5b57-9415-a352d4276950', 'SAL-01', 'Lire une fiche de paie et relier brut/net au budget', '', 'Prenez une fiche de paie anonymisée ou fictive. Surlignez : base, primes, retenues et net. Expliquez chaque ligne en une phrase.', 'Corrigé-type : repérer la période, le salaire de base, les éléments variables, les retenues sociales/fiscales et le net à payer. Le budget courant s’appuie sur le revenu net récurrent réellement disponible ; une prime exceptionnelle ne doit pas être assimilée à un revenu mensuel garanti.
INSERT IGNORE INTO `fin_academy_modules` (`id`, `formationId`, `courseId`, `quizId`, `code`, `title`, `level`, `exercise`, `correction`, `mission`, `challenge`, `tool`, `proof`, `evidenceType`, `regulatory`, `contentVersion`) VALUES ('0e6fd40c-8370-57fc-970a-ee2a20b211ee', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', '417badcc-8957-56e7-992e-8e68dbe5057c', 'TAX-01', 'Lire une obligation fiscale et sociale sans mémoriser des taux périssables', '', 'Choisissez un statut fictif. Écrivez les cinq informations nécessaires avant de calculer une obligation fiscale.', 'Corrigé-type : avant tout calcul, identifier au minimum : 1) statut juridique/fiscal ; 2) activité ; 3) revenu ou chiffre d’affaires et période ; 4) régime ou seuil applicable à la date considérée ; 5) source officielle et date de vérification. Ajouter la situation sociale/TVA lorsque pertinente.
INSERT IGNORE INTO `fin_academy_modules` (`id`, `formationId`, `courseId`, `quizId`, `code`, `title`, `level`, `exercise`, `correction`, `mission`, `challenge`, `tool`, `proof`, `evidenceType`, `regulatory`, `contentVersion`) VALUES ('d2264b2b-f5ea-5a1e-a662-514101fc8dea', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', '23d39037-6954-5f01-a25f-cf22baa57a66', 'c084cfc0-d51b-5d1c-8a5e-b05824b1a80d', 'ETH-01', 'Zakat : nisab, hawl, estimation et traçabilité méthodologique', '', 'Créez une fiche Zakat fictive avec : liquidités, marchandises, créances et éléments à vérifier. Indiquez ce qui nécessite un avis expert.', 'Corrigé-type : lister séparément liquidités, épargne, marchandises commerciales, créances et éléments incertains ; vérifier nisab et hawl selon la méthodologie retenue ; calculer uniquement sur la base éligible ; signaler tout cas religieux complexe pour avis qualifié. Le calculateur doit conserver année, source et hypothèses.
INSERT IGNORE INTO `fin_academy_modules` (`id`, `formationId`, `courseId`, `quizId`, `code`, `title`, `level`, `exercise`, `correction`, `mission`, `challenge`, `tool`, `proof`, `evidenceType`, `regulatory`, `contentVersion`) VALUES ('e30915a7-cfb5-5c36-9022-b69473ce1ac0', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'c313aa62-41fd-5324-ba86-290d461b7d4a', '6fa6bd96-560f-50a8-adc9-825ab05235a6', 'ESG-01', 'Finance verte : coût, économies, payback et risque', '', 'Évaluez un projet fictif d''efficacité énergétique avec coût, économies et trois scénarios de prix de l''énergie.', 'Corrigé-type : payback simple = investissement initial / économies annuelles. Construire un scénario bas, central et haut de prix/économies ; intégrer maintenance, durée de vie, financement et risques. Un payback court ne suffit pas à prouver la rentabilité globale ni l’impact réel.
